import java.util.Scanner;
public class JRentCar2 {
	public static void main(String[] args) {
		//Khatwa 1: Iqra al-madkhalat min wakil tajir al-sayarat
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil sin al-ameel:");
		int age = scan.nextInt();
		System.out.println("Adkhil hal al-ameel 3indahu rukhsa siyaqa (true aw false):");
		boolean hasLicense = scan.nextBoolean();	
		System.out.println("Adkhil hal al-ameel qad taarrad li hadath sayara (true aw false):");
		boolean hadAccidents = scan.nextBoolean();		
		scan.close();
		//Khatwa 2: Uktub al-ta'bir al-buliyani li tahdid hal yumkin lil-ameel istijar sayara
		boolean canRentCar = age >= 21 && hasLicense && !hadAccidents;
		System.out.println(canRentCar);
	}
}
